WITH with_windows AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, PERCENT_RANK() OVER (ORDER BY discount_pct ASC) AS discount_pct_percent_rank, LEAD(discount_pct, 2) OVER (PARTITION BY promo_code, channel ORDER BY ends_on ASC, id ASC) AS next_discount_pct, MIN(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_min_discount_pct, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY starts_on ASC, id ASC) AS event_seq, RANK() OVER w_part AS discount_pct_rank FROM promotions WINDOW w_part AS (ORDER BY discount_pct DESC)) SELECT DATE_TRUNC('YEAR', ends_on) AS year_start, COUNT(*) AS row_count, ROUND(AVG(next_discount_pct), 2) AS avg_next_discount_pct, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, SUM(CASE WHEN promo_code = 'WELCOME5' THEN next_discount_pct ELSE 0 END) AS welcome5_next_discount_pct, GROUPING_ID() AS grouping_id FROM with_windows GROUP BY ROLLUP (DATE_TRUNC('YEAR', ends_on)) HAVING avg_next_discount_pct < 0 ORDER BY row_count ASC
